create table public.areas (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,name text not null,color text not null default '#3F5A42',active boolean not null default true,created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
create table public.directions (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,title text not null,description text not null default '',horizon_start date,horizon_end date,status text not null default 'active',review_cadence text not null default 'quarterly',created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
create table public.goals (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,direction_id uuid references public.directions(id),title text not null,definition_of_done text not null default '',target_date date,status text not null default 'active',created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
alter table public.projects add column goal_id uuid references public.goals(id),add column area_id uuid references public.areas(id),add column type text not null default 'execute',add column target_date date;
create table public.milestones (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id),title text not null,target_date date,status text not null default 'pending',sort_order bigint not null default 0,created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
alter table public.tasks add column milestone_id uuid references public.milestones(id),add column area_id uuid references public.areas(id),add column context text,add column earliest_start_date date,add column is_commitment boolean not null default false;
create table public.notes (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id),title text not null,markdown_content text not null default '',created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
create table public.attachments (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id),task_id uuid references public.tasks(id),storage_path text not null,filename text not null,mime_type text not null,size_bytes bigint not null default 0,created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
create table public.planning_sessions (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,kind text not null,inputs jsonb not null default '{}',proposal jsonb,approved jsonb,status text not null default 'draft',created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
create table public.planning_profiles (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,work_days jsonb not null default '[1,2,3,4,5]',preferred_work_windows jsonb not null default '["09:00-17:00"]',daily_focus_minutes integer not null default 240,reserve_percent integer not null default 20,maximum_today_commitments integer not null default 3,minimum_task_minutes integer not null default 5,preferred_focus_session_minutes integer not null default 25,transition_buffer_minutes integer not null default 10,planning_detail text not null default 'balanced',breakdown_style text not null default 'mixed',prompt_tone text not null default 'gentle',deadline_buffer_days integer not null default 2,weekly_review_day integer not null default 0,reduce_decoration boolean not null default false,created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);
create table public.calendar_connections (id uuid primary key default gen_random_uuid(),owner_id uuid not null unique references auth.users(id) on delete cascade,provider text not null default 'google',encrypted_token_reference text,selected_calendars jsonb not null default '[]',privacy text not null default 'details',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.calendar_event_cache (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,external_id text not null,calendar_id text not null,title text not null,start_at timestamptz not null,end_at timestamptz not null,all_day boolean not null default false,travel boolean not null default false,privacy text not null default 'details',created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1,unique(owner_id,calendar_id,external_id));
create table public.agent_runs (id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,kind text not null,prompt_version text not null,model text not null,input jsonb not null,result jsonb,status text not null,feedback jsonb,created_at timestamptz not null,updated_at timestamptz not null,deleted_at timestamptz,version integer not null default 1);

alter table public.areas enable row level security;alter table public.directions enable row level security;alter table public.goals enable row level security;alter table public.milestones enable row level security;alter table public.notes enable row level security;alter table public.attachments enable row level security;alter table public.planning_sessions enable row level security;alter table public.planning_profiles enable row level security;alter table public.calendar_connections enable row level security;alter table public.calendar_event_cache enable row level security;alter table public.agent_runs enable row level security;
create policy owner_all_areas on public.areas for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_directions on public.directions for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_goals on public.goals for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_milestones on public.milestones for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_notes on public.notes for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_attachments on public.attachments for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_planning_sessions on public.planning_sessions for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_planning_profiles on public.planning_profiles for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_calendar_connections on public.calendar_connections for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_calendar_cache on public.calendar_event_cache for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_agent_runs on public.agent_runs for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());

create index milestones_project_idx on public.milestones(owner_id,project_id,sort_order);
create index notes_project_idx on public.notes(owner_id,project_id,updated_at desc);
create index calendar_cache_range_idx on public.calendar_event_cache(owner_id,start_at,end_at);
create index agent_runs_owner_created_idx on public.agent_runs(owner_id,created_at desc);
alter table public.calendar_event_cache alter column id set default gen_random_uuid();
